const date=()=>new Date().toISOString().slice(0,10);
const statusKey=s=>`clubStatus_${s}`;
const formatMoney=(r,lang)=>new Intl.NumberFormat(lang==='ar'?'ar':lang==='sv'?'sv-SE':'en-GB',{style:'currency',currency:r.currency,currencyDisplay:'code'}).format(r.amountMinor/100);
const open=(btn,t,key,op,id='')=>btn(t(key),'clubForm',`data-op="${op}" data-id="${id}"`,'secondary');
const direct=(btn,t,key,op,id)=>btn(t(key),'clubAction',`data-op="${op}" data-id="${id}"`,'secondary');
const badge=(t,status)=>`<span class="badge ${['active','paid'].includes(status)?'green':'gold'}">${t(statusKey(status))}</span>`;
const auditPanel=(entries,t,h)=>`<section class="card stack"><h2>${t('clubAudit')}</h2>${entries.map(a=>`<div class="rule"><b>${t('clubOp_'+a.operation)}</b> · ${h(a.actorName||t('clubFormerMember'))}<br><small>${h(new Date(a.at).toISOString())} · ${h(a.target)}</small></div>`).join('')||`<p class="empty">${t('noItems')}</p>`}</section>`;
const empty=t=>`<p class="empty">${t('noItems')}</p>`;
const invoiceRows=({invoices,t,h,btn,lang,write=false})=>invoices.map(i=>`<article class="rule stack"><div class="row space wrap"><b>#${h(i.number)} · ${h(i.label)}</b>${badge(t,i.status)}</div><p>${h(i.memberName||t('clubFormerMember'))} · ${h(formatMoney(i,lang))}</p><small>${t('clubIssued')}: ${h(i.date)} · ${t('clubDue')}: ${h(i.dueDate)}${i.paidDate?` · ${t('clubPaidDate')}: ${h(i.paidDate)}`:''}</small>${i.voidReason?`<small>${t('reason')}: ${h(i.voidReason)}</small>`:''}${write&&i.status!=='void'?`<div class="row wrap">${i.status==='issued'?open(btn,t,'clubMarkPaid','invoicePaid',h(i.id)):''}${open(btn,t,'clubVoid','invoiceVoid',h(i.id))}</div>`:''}</article>`).join('')||empty(t);
export function clubPage({state,t,h,btn,lang}){
  const c=state.clubOps;if(!c)return `<section class="card stack"><h2>${t('clubDirectory')}</h2><p>${t('clubContextRequired')}</p>${btn(t('identitySwitchLabel'),'nav','data-id="identity"','primary')}${state.profiles.filter(p=>p.role==='gym').map(p=>`<div class="rule"><b>${h(p.name)}</b><br><small>${h(p.city||'')}</small></div>`).join('')||empty(t)}</section>`;
  const manage=c.manage,club=state.identity.club;
  return `<div class="stack"><section class="hero workspace-hero"><span class="eyebrow">MUSCLIVO LIVE / CLUB</span><h1>${h(club.name)}</h1><p>${t('clubLocalNotice')}</p>${btn(t('identitySwitchLabel'),'nav','data-id="identity"','primary')}</section><section class="card stack"><div class="row space wrap"><h2>${t('branches')}</h2>${manage?open(btn,t,'clubAddBranch','branchCreate'):''}</div>${c.branches.map(b=>`<article class="rule stack"><div class="row space wrap"><b>${h(b.name)}</b>${badge(t,b.archived?'archived':'active')}</div><p>${h(b.city)} · ${h(b.address)}</p>${manage&&!b.archived?`<div class="row wrap">${open(btn,t,'wellnessEdit','branchUpdate',h(b.id))}${direct(btn,t,'clubArchive','branchArchive',h(b.id))}</div>`:''}</article>`).join('')||empty(t)}</section><section class="card stack"><div class="row space wrap"><h2>${t('clubPlans')}</h2>${manage?open(btn,t,'clubAddPlan','planCreate'):''}</div>${c.plans.map(p=>`<article class="rule stack"><div class="row space wrap"><b>${h(p.name)}</b>${badge(t,p.archived?'archived':'active')}</div><p>${h(formatMoney(p,lang))} · ${t('clubPeriod_'+p.period)}</p>${manage&&!p.archived?`<div class="row wrap">${open(btn,t,'wellnessEdit','planUpdate',h(p.id))}${direct(btn,t,'clubArchive','planArchive',h(p.id))}</div>`:''}</article>`).join('')||empty(t)}</section>${manage||state.identity.active.role==='member'?`<section class="card stack"><div class="row space wrap"><h2>${t('memberships')}</h2>${manage?open(btn,t,'clubAddMembership','membershipCreate'):''}</div>${c.memberships.map(m=>`<article class="rule stack"><div class="row space wrap"><b>${h(m.memberName||t('clubFormerMember'))} · ${h(m.planName)}</b>${badge(t,m.status)}</div><p>${h(formatMoney(m,lang))} · ${t('clubPeriod_'+m.period)}${m.branchName?` · ${h(m.branchName)}`:''}</p><small>${h(m.startDate)} — ${h(m.endDate)}</small>${manage&&!m.cancelledAt?direct(btn,t,'clubCancelMembership','membershipCancel',h(m.id)):''}</article>`).join('')||empty(t)}</section>`:''}${manage?`<section class="card stack"><h2>${t('identityRoster')}</h2>${state.identity.roster.map(r=>`<div class="rule"><b>${h(r.name)}</b> · ${t('identity_'+r.role)}</div>`).join('')||empty(t)}${btn(t('identity'),'nav','data-id="identity"','secondary')}</section>${auditPanel(c.audit,t,h)}`:''}${state.identity.active.role==='member'?`<section class="card stack"><h2>${t('invoices')}</h2>${invoiceRows({invoices:c.ownInvoices,t,h,btn,lang})}</section>`:''}${btn(t('clubChatTitle'),'clubChatNav','','primary')}${c.finance?btn(t('finance'),'nav','data-id="finance"','primary'):''}</div>`;
}
export function financePage({state,t,h,btn,lang}){
  const f=state.clubOps?.finance;if(!f)return `<section class="card stack"><p>${t('clubFinanceDenied')}</p></section>`;
  const total=(r,field)=>formatMoney({currency:r.currency,amountMinor:r[field]},lang);
  return `<div class="stack"><section class="hero workspace-hero"><span class="eyebrow">MUSCLIVO LIVE / FINANCE</span><h1>${t('finance')} · ${h(state.identity.club.name)}</h1><p>${t('clubFinanceNotice')}</p><span class="badge ${f.write?'green':'gold'}">${t(f.write?'clubFinanceWrite':'clubFinanceRead')}</span></section><section class="card stack"><h2>${t('financeReports')}</h2>${f.totals.map(r=>`<div class="rule stack"><b>${h(r.currency)}</b><div class="dashboard-metrics">${[['income','incomeMinor'],['expenses','expenseMinor'],['clubBalance','balanceMinor']].map(([k,v])=>`<div class="stat-box"><b>${h(total(r,v))}</b><br><small>${t(k)}</small></div>`).join('')}</div></div>`).join('')||empty(t)}</section><section class="card stack"><div class="row space wrap"><h2>${t('clubLedger')}</h2>${f.write?open(btn,t,'clubAddEntry','ledgerAdd'):''}</div>${f.ledger.map(e=>`<article class="rule stack"><div class="row space wrap"><b>${h(e.label)}</b>${badge(t,e.voidAt?'void':'active')}</div><p>${t(e.kind==='income'?'income':'expenses')} · ${h(formatMoney(e,lang))} · ${h(e.date)}</p>${e.voidReason?`<small>${t('reason')}: ${h(e.voidReason)}</small>`:''}${f.write&&!e.voidAt&&!e.invoiceId?open(btn,t,'clubVoid','ledgerVoid',h(e.id)):''}</article>`).join('')||empty(t)}</section><section class="card stack"><div class="row space wrap"><h2>${t('invoices')}</h2>${f.write?open(btn,t,'clubNewInvoice','invoiceCreate'):''}</div>${invoiceRows({invoices:f.invoices,t,h,btn,lang,write:f.write})}</section>${auditPanel(f.audit,t,h)}</div>`;
}
export function clubFormFields(op,row,c,t,h){
  const input=(name,label,value='',type='text',extra='')=>`<label>${t(label)}<input name="${name}" type="${type}" value="${h(value)}" ${extra}></label>`;
  const sel=(name,label,options,selected='')=>`<label>${t(label)}<select name="${name}" ${name==='branchId'?'':'required'}>${options.map(([v,l])=>`<option value="${h(v)}" ${v===selected?'selected':''}>${h(l)}</option>`).join('')}</select></label>`;
  const amount=r=>sel('currency','clubCurrency',['SEK','EUR','USD'].map(c=>[c,c]),r?.currency||'SEK')+input('amount','clubAmount',r?String((r.amountMinor/100).toFixed(2)):'','number','required min="0.01" max="1000000" step="0.01"');
  if(['branchCreate','branchUpdate'].includes(op))return input('name','name',row?.name,'text','required maxlength="80"')+input('city','city',row?.city,'text','required maxlength="80"')+input('address','clubAddress',row?.address,'text','maxlength="160"');
  if(['planCreate','planUpdate'].includes(op))return input('name','name',row?.name,'text','required maxlength="80"')+sel('period','clubPeriod',['monthly','annual','once'].map(p=>[p,t('clubPeriod_'+p)]),row?.period||'monthly')+amount(row);
  if(op==='membershipCreate')return sel('memberId','coachingSelectMember',[['',t('choosePeople')],...(c.members||[]).map(m=>[m.id,m.name])])+sel('planId','clubPlans',[['',t('choosePeople')],...c.plans.filter(p=>!p.archived).map(p=>[p.id,p.name])])+sel('branchId','branches',[['',t('clubNoBranch')],...c.branches.filter(b=>!b.archived).map(b=>[b.id,b.name])])+input('startDate','clubStart',date(),'date','required')+input('endDate','clubEnd',date(),'date','required');
  if(op==='ledgerAdd')return sel('kind','clubEntryType',[['income',t('income')],['expense',t('expenses')]])+input('label','clubDescription','','text','required maxlength="120"')+input('date','recordDate',date(),'date','required')+amount();
  if(op==='invoiceCreate')return sel('memberId','coachingSelectMember',[['',t('choosePeople')],...(c.finance?.billableMembers||[]).map(m=>[m.id,m.name])])+input('label','clubDescription','','text','required maxlength="120"')+input('date','clubIssued',date(),'date','required')+input('dueDate','clubDue',date(),'date','required')+amount();
  if(op==='invoicePaid')return `<p>${t('clubManualPayment')}</p>`+input('date','clubPaidDate',date(),'date','required');
  if(['invoiceVoid','ledgerVoid'].includes(op))return `<p>${t('clubVoidNotice')}</p>`+input('reason','reason','','text','required maxlength="160"');
  return '';
}
export function clubFormPayload(data){
  const result={...data};if(Object.hasOwn(result,'amount')){const m=/^(0|[1-9]\d*)(?:\.(\d{1,2}))?$/.exec(result.amount);result.amountMinor=m?Number(m[1])*100+Number((m[2]||'').padEnd(2,'0')):NaN;delete result.amount}return result;
}
